  <button id="tabSample" class="active" onclick="loadTab('sample')">Sample</button>
  <button id="tabBuggy" onclick="loadTab('buggy')">Buggy</button>
  <button id="tabStarter" onclick="loadTab('starter')">Starter</button>
</div>
<textarea id="bellmanFordRelaxCode" spellcheck="false"></textarea>
<label style="font-size:12px">Edge relaxation order (4 passes)
  <input id="edgeOrderInput" type="text" value="(t,x),(t,y),(t,z),(x,t),(y,x),(y,z),(z,x),(z,s),(s,t),(s,y)" style="width:100%;box-sizing:border-box;font-family:monospace;font-size:11px">
</label>
<button id="runBtn" onclick="triggerRun()">▶ Run relax() over passes</button>
<div style="display:flex;gap:5px;align-items:center">
  <button onclick="pbFirst()">⏮</button><button onclick="pbPrev()">◀</button>
  <button id="playBtn" onclick="pbPlay()">▶</button><button onclick="pbNext()">▶|</button>
  <label style="flex-direction:row;align-items:center;gap:4px;font-size:12px">spd<input id="speedInput" type="range" min="1" max="20" value="6" style="width:54px"></label>
</div>
