<span id="statusSpan" style="font-size:12px;font-weight:bold;color:#777">status: not run</span>
<div id="logDiv" style="font-family:monospace;font-size:11px;line-height:1.4;max-height:110px;overflow-y:auto;background:#f4f4f6;border:1px solid #ddd;border-radius:4px;padding:5px;white-space:pre-wrap"></div>
