    el.style.color=map[s][1];
  }

  function runCode(code,orderStr,onDone){
    stopPlay();
    var order=parseOrder(orderStr);
    if(!order.length){setStatus('error','no edges parsed');return;}
    setStatus('running');
    var rb=document.getElementById('runBtn'); if(rb)rb.disabled=true;
    var src=buildWorkerSrc();
    var blob=new Blob([src],{type:'application/javascript'});
    var url=URL.createObjectURL(blob);
    var wk=new Worker(url);
    var finished=false;
    var to=setTimeout(function(){if(!finished){finished=true;wk.terminate();URL.revokeObjectURL(url);setStatus('error','timeout');if(rb)rb.disabled=false;}},2500);
    wk.onmessage=function(ev){
      if(finished)return;finished=true;clearTimeout(to);wk.terminate();URL.revokeObjectURL(url);
      if(rb)rb.disabled=false;
      var m=ev.data;frames=m.frames||[];
      // map panels a..e to init + first four passEnd frames
      panelFrames={a:0,b:-1,c:-1,d:-1,e:-1};
      var pe=[];
      for(var i=0;i<frames.length;i++){if(frames[i].kind==='passEnd')pe.push(i);}
      panelFrames.b=pe[0]!=null?pe[0]:-1;
      panelFrames.c=pe[1]!=null?pe[1]:-1;
      panelFrames.d=pe[2]!=null?pe[2]:-1;
      panelFrames.e=pe[3]!=null?pe[3]:(frames.length-1);
      if(m.type==='error'){finalState=null;wrongVerts=[];setStatus('error',m.message);render(frames.length?frames.length-1:0);onDone&&onDone();return;}
      finalState=m.final;wrongVerts=[];
      var ok=finalState&&finalState.convergedAt>=1&&finalState.convergedAt<=5;
      Object.keys(TARGET).forEach(function(v){if(!ok||finalState.dist[v]!==TARGET[v]){ok=false;if(wrongVerts.indexOf(v)<0)wrongVerts.push(v);}});
      if(ok){setStatus('correct','d = {s:0,t:2,x:4,y:7,z:-2}, converged pass '+finalState.convergedAt);}
      else{setStatus('wrong','estimates do not match the shortest-path tree');}
      render(0);
      onDone&&onDone();
    };
    wk.onerror=function(e){if(finished)return;finished=true;clearTimeout(to);wk.terminate();URL.revokeObjectURL(url);if(rb)rb.disabled=false;setStatus('error',e.message);onDone&&onDone();};
    wk.postMessage({order:order,code:code,weights:WEIGHTS});
  }

  function goPanel(letter){
    var idx=panelFrames[letter];
    if(idx==null||idx<0){setStatus('error','run the sample first to populate panel ('+letter+')');return;}
    stopPlay();render(idx);
  }
  window.goPanel=goPanel;

  var SAMPLE="function relax(u, v, w) {\n  if (getDist(u) + w < getDist(v)) {\n    setDist(v, getDist(u) + w);\n    setPred(v, u);\n    highlightEdge(u, v);\n  }\n}";
  var BUGGY="function relax(u, v, w) {\n  // BUG: comparison is backwards, so distances only ever increase\n  if (getDist(u) + w > getDist(v)) {\n    setDist(v, getDist(u) + w);\n    setPred(v, u);\n    highlightEdge(u, v);\n  }\n}";
  var STARTER="function relax(u, v, w) {\n  // TODO: only lower d[v] when u's path + w is shorter\n}";
  function setTab(id){['tabSample','tabBuggy','tabStarter'].forEach(function(t){var e=document.getElementById(t);if(e)e.classList.remove('active');});var e=document.getElementById(id);if(e)e.classList.add('active');}
  function loadTab(t){
    var ta=document.getElementById('bellmanFordRelaxCode'); if(!ta)return;
    if(t==='sample'){ta.value=SAMPLE;setTab('tabSample');}
    else if(t==='buggy'){ta.value=BUGGY;setTab('tabBuggy');}
    else{ta.value=STARTER;setTab('tabStarter');}
  }
  window.loadTab=loadTab;

  function triggerRun(){
    runCode(document.getElementById('bellmanFordRelaxCode').value,document.getElementById('edgeOrderInput').value,null);
  }
  window.triggerRun=triggerRun;

  var stepIdx=0;
  var STEPS=[
    {n:'The source starts at d[s]=0 and every other vertex at ∞. Run the first pass: only the edges leaving s (s→t, s→y) can improve anything, giving d[t]=6 and d[y]=7. The gray tree now holds s→t and s→y.',
     act:function(cb){loadTab('sample');runCode(SAMPLE,document.getElementById('edgeOrderInput').value,function(){goPanel('b');cb&&cb();});}},
    {n:'Now that t and y are finite, edges out of them fire: t→z and the negative edge y→x bring d[x]=4 and d[z]=2. The gray predecessor tree grows to s→t, s→y, y→x, t→z (panel c).',
     act:function(cb){loadTab('sample');runCode(SAMPLE,document.getElementById('edgeOrderInput').value,function(){goPanel('c');cb&&cb();});}},
    {n:'Negative edges keep pulling estimates down: x→t lowers d[t] to 2 (re-parenting t under x) and t→z lowers d[z] to −2. A final pass changes nothing → converged to the tree s→y→x→t→z (panels d–e).',
     act:function(cb){loadTab('sample');runCode(SAMPLE,document.getElementById('edgeOrderInput').value,function(){goPanel('e');cb&&cb();});}},
    {n:'Load the buggy version (comparison reversed) and run again: estimates climb instead of falling and never match the target, showing that relax must only ever DECREASE d[v].',
     act:function(cb){loadTab('buggy');runCode(BUGGY,document.getElementById('edgeOrderInput').value,function(){render(frames.length-1);cb&&cb();});}}
  ];
  function showStep(){
    var n=document.getElementById('demoNarration'); if(n)n.textContent=STEPS[stepIdx].n;
    var sl=document.getElementById('stepLabel'); if(sl)sl.textContent='Step '+(stepIdx+1)+'/'+STEPS.length;
    STEPS[stepIdx].act();
  }
  function nextStep(){stepIdx=(stepIdx+1)%STEPS.length;showStep();}
  function prevStep(){stepIdx=(stepIdx-1+STEPS.length)%STEPS.length;showStep();}
  window.nextStep=nextStep;window.prevStep=prevStep;

  loadTab('sample');
  render(0);
  var n=document.getElementById('demoNarration'); if(n)n.textContent=STEPS[0].n;
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Bellman-Ford repeatedly relaxes every edge, and because negative-weight edges can shorten paths found earlier, distance estimates keep decreasing over successive passes until a full pass changes nothing.
KEY INSIGHT (what students should walk away understanding): Each Bellman-Ford pass can extend the known shortest path by at most one edge, so negative-weight edges force you to keep relaxing for up to |V|-1 passes until a whole pass produces no change.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Bellman-Ford repeatedly relaxes every edge, and because negative-weight edges can shorten paths found earlier, distance estimates keep decreasing over successive passes until a full pass changes nothing.",
  "figureType": "network_diagram",
  "elements": [
    "vertex s (left) circle with d[s] label inside",
    "vertex t (upper-center) circle with d[t] label inside",
    "vertex y (lower-center) circle with d[y] label inside",
    "vertex x (upper-right) circle with d[x] label inside",
    "vertex z (lower-right) circle with d[z] label inside",
    "directed edge s→t, weight 6",
    "directed edge s→y, weight 7",
    "directed edge t→x, weight 5",
    "directed edge x→t, weight -2 (curved, paired with t→x)",
    "directed edge t→y, weight 8",
    "directed edge y→x, weight -3",
    "directed edge t→z, weight -4",
    "directed edge y→z, weight 9",
    "directed edge z→x, weight 7",
    "directed edge z→s, weight 2",
    "gray bold overlay on edges relaxed (improved a distance) in the current pass",
    "per-pass counter annotation: number of distance estimates changed this pass",
    "pass indicator label (Pass 1..4 / converged)"
  ],
  "interactions": [
    {
      "id": "bellmanFordRelax",
      "type": "code_editor",
      "label": "Implement relax(u, v, w)",
      "entry_point": "relax(u, v, w)",
      "api": [
        {
          "op": "getDist(v)",
          "does": "returns the current shortest-path estimate d[v] (Infinity if unreached)"
        },
        {
          "op": "setDist(v, val)",
          "does": "set d[v] = val — the ONLY way to change a distance estimate"
        },
        {
          "op": "setPred(v, u)",
          "does": "record u as v's predecessor on the current best path"
        },
        {
          "op": "highlightEdge(u, v)",
          "does": "shade edge (u,v) gray to mark it as relaxed-and-improved this pass"
        },
        {
          "op": "note(msg)",
          "does": "attach a short commentary label to the current frame (learner's own annotation)"
        }
      ],
      "frame": "the whole 5-vertex graph with the current d[] value inside each circle, edges improved this pass shaded gray, and a counter of how many estimates changed this pass",
      "input": {
        "label": "Edge relaxation order (4 passes)",
        "default": "(t,x),(t,y),(t,z),(x,t),(y,x),(y,z),(z,x),(z,s),(s,t),(s,y)"
      },
      "sample_code": "function relax(u, v, w) {\n  if (getDist(u) + w < getDist(v)) {\n    setDist(v, getDist(u) + w);\n    setPred(v, u);\n    highlightEdge(u, v);\n  }\n}",
      "buggy_code": "function relax(u, v, w) {\n  // BUG: comparison is backwards, so distances only ever increase\n  if (getDist(u) + w > getDist(v)) {\n    setDist(v, getDist(u) + w);\n    setPred(v, u);\n    highlightEdge(u, v);\n  }\n}",
      "success_check": "after 4 passes the estimates are d[s]=0, d[t]=2, d[x]=4, d[y]=7, d[z]=-2, the gray edges form the shortest-path tree s→y→x→t→z, and a 5th pass changes nothing",
      "teaches": "Relaxation only ever lowers an estimate, and one pass can only propagate a path one edge longer than the previous pass — so with negative edges you need up to |V|-1 passes before the true shortest paths stop improving"
    }
  ],
  "demo_steps": [
    {
      "title": "Initial state (panel a)",
      "narration": "The source starts at d[s]=0 and every other vertex at ∞. Run the first pass: only the edges leaving s (s→t, s→y) can improve anything, giving d[t]=6 and d[y]=7.",
      "state": {}
    },
    {
      "title": "Pass 2 (panels b–c)",
      "narration": "Now that t and y are finite, edges out of them fire: t→x and y→z (and via the negative edge y→x) bring d[x]=4 and d[z]=2. Watch the gray set grow as more vertices become reachable.",
      "state": {}
    },
    {
      "title": "Pass 3 and convergence (panels d–e)",
      "narration": "Negative edges keep pulling estimates down: x→t lowers d[t] to 2 and t→z lowers d[z] to -2. A final pass changes nothing, so the algorithm has converged to the shortest-path tree s→y→x→t→z.",
      "state": {}
    },
    {
      "title": "Break it on purpose",
      "narration": "Load the buggy version (comparison reversed) and run again: estimates climb instead of falling and never match the target, showing that relax must only ever DECREASE d[v].",
      "state": {}
    }
  ],
  "keyInsight": "Each Bellman-Ford pass can extend the known shortest path by at most one edge, so negative-weight edges force you to keep relaxing for up to |V|-1 passes until a whole pass produces no change.",
  "reconstructionNotes": "Single live graph replaces the five static panels: s on the far left, t upper-center, y lower-center, x upper-right, z lower-right, matching the textbook layout so edge crossings (t→z vs y→x) read the same. Vertex circles light-gray fill with the current d[] value centered inside (use ∞ symbol before first improvement). Default edges thin black arrows with weight labels beside them; negative weights shown with a leading minus. Edges improved in the current pass drawn as thick gray arrows underneath the black arrowhead. A small counter chip (e.g. 'Pass 2 · 2 changed') sits top-right. Animate d[] label changes with a brief highlight pulse when setDist fires, and cross-fade the gray edge shading per pass so the replay reads as the (a)→(e) sequence."
}

