// @FIGURE_CODE_BEGIN
(function(){
  var W=1000,H=640;
  var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
  draw.viewbox(0,0,W,H);

  var POS={s:{x:110,y:320},t:{x:430,y:120},y:{x:430,y:520},x:{x:770,y:120},z:{x:770,y:520}};
  var R=27;
  var EDGES=[
    {u:'s',v:'t',w:6,lx:245,ly:195},
    {u:'s',v:'y',w:7,lx:245,ly:455},
    {u:'t',v:'x',w:5,curve:{x:600,y:52},lx:600,ly:46},
    {u:'x',v:'t',w:-2,curve:{x:600,y:170},lx:600,ly:152},
    {u:'t',v:'y',w:8,lx:400,ly:325},
    {u:'y',v:'x',w:-3,lx:640,ly:280},
    {u:'t',v:'z',w:-4,lx:640,ly:360},
    {u:'y',v:'z',w:9,lx:600,ly:562},
    {u:'z',v:'x',w:7,lx:802,ly:325},
    {u:'z',v:'s',w:2,lx:440,ly:400}
  ];
  var WEIGHTS={};
  EDGES.forEach(function(e){WEIGHTS[e.u+'->'+e.v]=e.w;});
  var TARGET={s:0,t:2,x:4,y:7,z:-2};

  var mB=draw.marker(11,11,function(a){a.path('M0,0 L11,5.5 L0,11 z').fill('#000');});
  mB.attr({orient:'auto',refX:9,refY:5.5});
  var mG=draw.marker(14,14,function(a){a.path('M0,0 L14,7 L0,14 z').fill('#8f8f8f');});
  mG.attr({orient:'auto',refX:11,refY:7});

  function edgeGeom(e){
    var A=POS[e.u],B=POS[e.v];
    var dx=B.x-A.x,dy=B.y-A.y,len=Math.sqrt(dx*dx+dy*dy),ux=dx/len,uy=dy/len;
    var sx=A.x+ux*R,sy=A.y+uy*R,ex=B.x-ux*(R+3),ey=B.y-uy*(R+3);
    if(e.curve){return 'M'+sx+','+sy+' Q'+e.curve.x+','+e.curve.y+' '+ex+','+ey;}
    return 'M'+sx+','+sy+' L'+ex+','+ey;
  }

  var gGray=draw.group(), gEdge=draw.group(), gNode=draw.group(), gLbl=draw.group(), gTop=draw.group();
  var grayPaths=[], blackPaths=[], nodeCirc={}, nodeDist={}, ringEls={};

  EDGES.forEach(function(e,i){
    var d=edgeGeom(e);
    grayPaths.push(gGray.path(d).fill('none').stroke({color:'#9a9a9a',width:10,linecap:'round'}).attr('marker-end',mG).opacity(0));
    blackPaths.push(gEdge.path(d).fill('none').stroke({color:'#000',width:1.6}).attr('marker-end',mB));
    gLbl.text(String(e.w)).attr({x:e.lx,y:e.ly,'text-anchor':'middle','font-size':18,'font-family':'Georgia, serif','paint-order':'stroke',stroke:'#fff','stroke-width':3,'stroke-linejoin':'round'});
  });

  Object.keys(POS).forEach(function(v){
    var p=POS[v];
    ringEls[v]=gTop.circle(R*2+12).center(p.x,p.y).fill('none').stroke({color:'#ff8c00',width:3}).opacity(0);
    nodeCirc[v]=gNode.circle(R*2).center(p.x,p.y).fill('#d9d9d9').stroke({color:'#000',width:1.5});
    nodeDist[v]=gNode.text('∞').attr({x:p.x,y:p.y+7,'text-anchor':'middle','font-size':20,'font-weight':'bold','font-family':'Georgia, serif'});
    var off={s:{dx:-36,dy:7},t:{dx:0,dy:-40},y:{dx:0,dy:50},x:{dx:0,dy:-40},z:{dx:0,dy:50}}[v];
    gNode.text(v).attr({x:p.x+off.dx,y:p.y+off.dy,'text-anchor':'middle','font-size':20,'font-style':'italic','font-family':'Georgia, serif'});
  });

  // Fixed: use .rect().radius() instead of .roundedRect() which doesn't exist in SVG.js v3
  var chipRect=gTop.rect(230,36).radius(8).attr({x:W-245,y:12,fill:'#fff',stroke:'#999','stroke-width':1});
  var chipText=gTop.text('ready — press Run').attr({x:W-130,y:35,'text-anchor':'middle','font-size':16,'font-family':'sans-serif',fill:'#333'});

  function fmt(v){return v===Infinity?'∞':String(v);}

  var frames=[], cur=0, finalState=null, wrongVerts=[], status='not-run';
  var panelFrames={a:0,b:-1,c:-1,d:-1,e:-1};

  function render(i){
    if(!frames.length){
      Object.keys(POS).forEach(function(v){nodeDist[v].text(v==='s'?'0':'∞');nodeCirc[v].stroke({color:'#000',width:1.5});ringEls[v].opacity(0);});
      grayPaths.forEach(function(g){g.opacity(0);});
      chipText.text('ready — press Run');
      var cap=document.getElementById('caption'); if(cap)cap.textContent='Initial: d[s]=0, all others ∞. Gray bold arrows show the cumulative shortest-path predecessor tree.';
      var fc=document.getElementById('frameCounter'); if(fc)fc.textContent='0 of 0';
      var lg=document.getElementById('logDiv'); if(lg)lg.textContent='';
      return;
    }
    i=Math.max(0,Math.min(frames.length-1,i)); cur=i;
    var f=frames[i], st=f.state;
    Object.keys(POS).forEach(function(v){
      nodeDist[v].text(fmt(st.dist[v]));
      var isWrong=(status==='wrong' && i===frames.length-1 && wrongVerts.indexOf(v)>=0);
      nodeCirc[v].stroke({color:isWrong?'#c00000':'#000',width:isWrong?3:1.5});
      var ringOn=(f.indices&&f.indices.indexOf(v)>=0 && f.kind!=='pass'&&f.kind!=='passEnd'&&f.kind!=='init'&&f.kind!=='converged');
      ringEls[v].opacity(ringOn?0.9:0).stroke({color:isWrong?'#c00000':'#ff8c00'});
    });
    // cumulative predecessor tree = gray bold arrows
    EDGES.forEach(function(e,k){
      var on = st.pred && st.pred[e.v]===e.u;
      grayPaths[k].opacity(on?0.85:0);
    });
    chipText.text('Pass '+st.pass+' · '+st.changed+' changed');
    var cap=document.getElementById('caption'); if(cap)cap.textContent=f.message||'—';
    var fc=document.getElementById('frameCounter'); if(fc)fc.textContent=(i+1)+' of '+frames.length;
    var lg=document.getElementById('logDiv');
    if(lg){var log='';for(var k=Math.max(0,i-22);k<=i;k++){log+='['+k+'] '+frames[k].message+'\n';}lg.textContent=log;lg.scrollTop=99999;}
  }

  var playing=false, timer=null;
  function stopPlay(){playing=false;clearInterval(timer);var b=document.getElementById('playBtn');if(b)b.textContent='▶';}
  function pbFirst(){stopPlay();render(0);}
  function pbPrev(){stopPlay();render(cur-1);}
  function pbNext(){stopPlay();render(cur+1);}
  function pbPlay(){
    if(!frames.length)return;
    if(playing){stopPlay();return;}
    playing=true;var b=document.getElementById('playBtn');if(b)b.textContent='⏸';
    timer=setInterval(function(){
      var spd=21-(+document.getElementById('speedInput').value);
      if(cur>=frames.length-1){stopPlay();return;}
      render(cur+1);
    },Math.max(40,spd*40));
  }
  window.pbFirst=pbFirst;window.pbPrev=pbPrev;window.pbNext=pbNext;window.pbPlay=pbPlay;

  function parseOrder(s){
    var out=[],re=/\s*\(\s*([a-z])\s*,\s*([a-z])\s*\)\s*/g,m;
    while((m=re.exec(s))){out.push([m[1],m[2]]);}
    return out;
  }

  function buildWorkerSrc(){
    return [
      'self.onmessage=function(ev){',
      ' var data=ev.data,order=data.order,userCode=data.code,W=data.weights;',
      ' var dist={s:0,t:Infinity,y:Infinity,x:Infinity,z:Infinity};',
      ' var pred={s:null,t:null,y:null,x:null,z:null};',
      ' var changed=0,pass=0,frames=[],opCount=0,MAXOPS=20000,MAXFRAMES=4000;',
      ' function fmt(v){return v===Infinity?"inf":v;}',
      ' function snap(kind,indices,message){if(frames.length<MAXFRAMES)frames.push({kind:kind,state:{dist:{s:dist.s,t:dist.t,y:dist.y,x:dist.x,z:dist.z},pred:{s:pred.s,t:pred.t,y:pred.y,x:pred.x,z:pred.z},changed:changed,pass:pass},indices:indices||[],message:message});}',
      ' function chk(){opCount++;if(opCount>MAXOPS)throw new Error("operation cap exceeded (infinite loop?)");}',
      ' var api={',
      '  getDist:function(v){chk();snap("getDist",[v],"getDist("+v+") = "+fmt(dist[v]));return dist[v];},',
      '  setDist:function(v,val){chk();dist[v]=val;changed++;snap("setDist",[v],"setDist("+v+", "+fmt(val)+")  <- estimate lowered");},',
      '  setPred:function(v,u){chk();pred[v]=u;snap("setPred",[v],"setPred("+v+", "+u+")  <- tree edge "+u+"->"+v);},',
      '  highlightEdge:function(u,v){chk();snap("highlightEdge",[u,v],"relaxed "+u+"->"+v+" (improved)");},',
      '  note:function(m){chk();snap("note",[],String(m));}',
      ' };',
      ' snap("init",[],"initial: d[s]=0, all others inf");',
      ' var relaxFn;',
      ' try{relaxFn=new Function("getDist","setDist","setPred","highlightEdge","note",userCode+"\\n;return (typeof relax===\\"function\\")?relax:null;")(api.getDist,api.setDist,api.setPred,api.highlightEdge,api.note);}',
      ' catch(e){self.postMessage({type:"error",message:"Syntax error: "+e.message,frames:frames});return;}',
      ' if(!relaxFn){self.postMessage({type:"error",message:"entry_point relax(u,v,w) not defined",frames:frames});return;}',
      ' var convergedAt=-1;',
      ' try{',
      '  for(pass=1;pass<=5;pass++){',
      '   changed=0;snap("pass",[],"== Pass "+pass+" : relax every edge ==");',
      '   for(var i=0;i<order.length;i++){var u=order[i][0],v=order[i][1];relaxFn(u,v,W[u+"->"+v]);}',
      '   snap("passEnd",[],"end of pass "+pass+": "+changed+" estimate(s) changed");',
      '   if(changed===0){convergedAt=pass;snap("converged",[],"Pass "+pass+" changed nothing -> CONVERGED");break;}',
      '  }',
      ' }catch(e){self.postMessage({type:"error",message:"Runtime error: "+e.message,frames:frames});return;}',
      ' self.postMessage({type:"done",frames:frames,final:{dist:{s:dist.s,t:dist.t,y:dist.y,x:dist.x,z:dist.z},pred:pred,convergedAt:convergedAt}});',
      '};'
    ].join("\n");
  }

  function setStatus(s,extra){
    status=s;
    var el=document.getElementById('statusSpan'); if(!el)return;
    var map={'not-run':['not run','#777'],'running':['running…','#1f77b4'],'correct':['CORRECT ✓','#1a7f1a'],'wrong':['WRONG ANSWER ✗','#c00000'],'error':['ERROR','#c00000']};
    el.textContent='status: '+map[s][0]+(extra?' — '+extra:'');
    el.style.color=map[s][1];
  }

  function runCode(code,orderStr,onDone){
    stopPlay();
    var order=parseOrder(orderStr);
    if(!order.length){setStatus('error','no edges parsed');return;}
    setStatus('running');
    var rb=document.getElementById('runBtn'); if(rb)rb.disabled=true;
    var src=buildWorkerSrc();
    var blob=new Blob([src],{type:'application/javascript'});
    var url=URL.createObjectURL(blob);
    var wk=new Worker(url);
    var finished=false;
    var to=setTimeout(function(){if(!finished){finished=true;wk.terminate();URL.revokeObjectURL(url);setStatus('error','timeout');if(rb)rb.disabled=false;}},2500);
    wk.onmessage=function(ev){
      if(finished)return;finished=true;clearTimeout(to);wk.terminate();URL.revokeObjectURL(url);
      if(rb)rb.disabled=false;
      var m=ev.data;frames=m.frames||[];
      // map panels a..e to init + first four passEnd frames
      panelFrames={a:0,b:-1,c:-1,d:-1,e:-1};
      var pe=[];
      for(var i=0;i<frames.length;i++){if(frames[i].kind==='passEnd')pe.push(i);}
      panelFrames.b=pe[0]!=null?pe[0]:-1;
      panelFrames.c=pe[1]!=null?pe[1]:-1;
      panelFrames.d=pe[2]!=null?pe[2]:-1;
      panelFrames.e=pe[3]!=null?pe[3]:(frames.length-1);
      if(m.type==='error'){finalState=null;wrongVerts=[];setStatus('error',m.message);render(frames.length?frames.length-1:0);onDone&&onDone();return;}
      finalState=m.final;wrongVerts=[];
      var ok=finalState&&finalState.convergedAt>=1&&finalState.convergedAt<=5;
      Object.keys(TARGET).forEach(function(v){if(!ok||finalState.dist[v]!==TARGET[v]){ok=false;if(wrongVerts.indexOf(v)<0)wrongVerts.push(v);}});
      if(ok){setStatus('correct','d = {s:0,t:2,x:4,y:7,z:-2}, converged pass '+finalState.convergedAt);}
      else{setStatus('wrong','estimates do not match the shortest-path tree');}
      render(0);
      onDone&&onDone();
    };
    wk.onerror=function(e){if(finished)return;finished=true;clearTimeout(to);wk.terminate();URL.revokeObjectURL(url);if(rb)rb.disabled=false;setStatus('error',e.message);onDone&&onDone();};
    wk.postMessage({order:order,code:code,weights:WEIGHTS});
  }

